/**
 * The `AutoGeneratedType` vocabulary shared by every producer in this stage
 * (the generateAutoTypes orchestrator, the inline-union generator, the
 * inline-enum converter, and the discriminator-/typename-based resolveType
 * generators), plus its two context-independent constructors.
 */

import {
  type DeprecationInfo,
  type FieldInfo,
  type GraphQLFieldType,
  type InlineObjectMember,
  PRIMITIVE_TYPE_MAP,
  type PropertyDef,
  type SourceLocation,
  type TSTypeReference,
} from "../core/index.js";
import type { AutoTypeNameContext } from "./naming-convention.js";
import type { ResolveTypeFieldPattern } from "./resolve-type-generator.js";

/**
 * Information about where an auto-generated type was generated from.
 */
export interface GeneratedFromInfo {
  readonly parentTypeName: string | null;
  readonly fieldPath: ReadonlyArray<string>;
  readonly context:
    | "typeField"
    | "inputField"
    | "resolverArg"
    | "resolverPayload";
}

/**
 * Enum value information for auto-generated enum types.
 */
export interface AutoGeneratedEnumValue {
  /** GraphQL enum value name (SCREAMING_SNAKE_CASE) */
  readonly name: string;
  /** Original TypeScript value */
  readonly originalValue: string;
  readonly description: string | null;
  readonly deprecated: DeprecationInfo | null;
}

/**
 * Auto-generated type information.
 */
export interface AutoGeneratedType {
  readonly name: string;
  readonly kind:
    | "Object"
    | "InputObject"
    | "Enum"
    | "Union"
    | "OneOfInputObject";
  /** Fields for Object/InputObject/OneOfInputObject kinds (null for Enum/Union) */
  readonly fields: ReadonlyArray<FieldInfo> | null;
  /** Enum values for Enum kind (null for Object/InputObject/Union/OneOfInputObject) */
  readonly enumValues: ReadonlyArray<AutoGeneratedEnumValue> | null;
  /** Union members for Union kind (null for Object/InputObject/Enum/OneOfInputObject) */
  readonly unionMembers: ReadonlyArray<string> | null;
  /** True if enum needs value mapping (at least one value converted) */
  readonly needsStringEnumMapping: boolean;
  readonly sourceLocation: SourceLocation;
  readonly generatedFrom: GeneratedFromInfo;
  readonly description: string | null;
  /**
   * Deprecation info from the `@deprecated` TSDoc tag on the source inline
   * object type alias or external enum type (null when no such source
   * exists, e.g. anonymous union-member types synthesized without a type
   * alias — refactor-plan.md §1.3 bug #9).
   */
  readonly deprecated: DeprecationInfo | null;
  /** For Union types from resolverPayload context: the field pattern for resolveType */
  readonly resolveTypeFieldPattern: ResolveTypeFieldPattern | null;
}

function mapContextKindToGeneratedFromContext(
  kind: AutoTypeNameContext["kind"],
): GeneratedFromInfo["context"] {
  switch (kind) {
    case "objectField":
      return "typeField";
    case "inputField":
      return "inputField";
    case "resolverArg":
      return "resolverArg";
    case "resolverPayload":
      return "resolverPayload";
  }
}

export function buildGeneratedFromInfo(
  context: AutoTypeNameContext,
): GeneratedFromInfo {
  const fieldPath =
    context.kind === "resolverArg" && context.fieldPath.length === 0
      ? [context.argName]
      : context.fieldPath;

  return {
    parentTypeName: context.parentTypeName,
    fieldPath,
    context: mapContextKindToGeneratedFromContext(context.kind),
  };
}

export interface GenerateObjectTypeFromInlineObjectParams {
  readonly inlineObjectMember: InlineObjectMember;
  readonly typeName: string;
  readonly abstractTypeName: string;
  readonly sourceFile: string;
  readonly skipPropertyNames: ReadonlySet<string>;
}

function primitiveToGraphQLScalar(primitive: string): string {
  return PRIMITIVE_TYPE_MAP[primitive] ?? "String";
}

/**
 * PRESERVED LEGACY BEHAVIOR (do not "fix" this without a deliberate follow-up
 * change): this reproduces, kind-for-kind, the bespoke TSType->GraphQLFieldType
 * conversion that `auto-type-generator/inline-object-converter.ts` used before
 * it was deleted in favor of the shared `convertTsTypeToGraphQLType` (commit
 * 0bbd626). That shared converter is strictly more correct — it properly
 * handles `stringLiteral`/`numericLiteral`/`union`/`never` kinds and emits
 * `__INLINE_OBJECT__`/`__INLINE_ENUM__` sentinels for nested inline
 * object/enum kinds so a later pass can resolve them to generated type names.
 * But union-member field assembly (this function) has no such resolution
 * pass, so those sentinels leaked verbatim into the generated schema
 * (observed as `__INLINE_OBJECT__`/`__INLINE_ENUM__` field types on
 * `examples/with-ai-sdk`'s union members, whose members are unions/inline
 * objects/string-literal unions sourced from the external `ai` package).
 *
 * The old weak converter only handled `array`/`reference`/`primitive`/
 * `scalar` kinds and silently fell back to `"String"` for everything else
 * (`stringLiteral`, `numericLiteral`, `union`, `never`, `inlineObject`,
 * `inlineEnum`). That means nested inline types inside union members
 * silently degrade to `String` today — a real, pre-existing bug — but this
 * function keeps reproducing that exact fallback so output stays
 * byte-identical to pre-refactor behavior. Routing these properties through
 * proper auto-type generation (so nested inline types in union members
 * resolve to real generated types instead of degrading) is the correct fix,
 * deliberately deferred to a later change.
 */
function convertUnionMemberPropertyType(
  property: PropertyDef,
): GraphQLFieldType {
  const tsType: TSTypeReference = property.tsType;
  // Note: `nullable` intentionally comes from `tsType.nullable` alone, same
  // as the deleted converter — `property.optional` was never consulted here
  // (a latent quirk of the old code, preserved rather than "corrected").
  const nullable = tsType.nullable;
  let typeName: string;
  let list = false;
  let listItemNullable: boolean | null = null;

  if (tsType.kind === "array" && tsType.elementType) {
    list = true;
    listItemNullable = tsType.elementType.nullable;
    const elementName = tsType.elementType.name ?? "String";
    typeName =
      tsType.elementType.kind === "primitive"
        ? primitiveToGraphQLScalar(elementName)
        : elementName;
  } else if (tsType.kind === "reference" && tsType.name) {
    typeName = tsType.name;
  } else if (tsType.kind === "primitive" && tsType.name) {
    typeName = primitiveToGraphQLScalar(tsType.name);
  } else if (tsType.kind === "scalar" && tsType.scalarInfo) {
    typeName = tsType.scalarInfo.scalarName;
  } else {
    typeName = "String";
  }

  return { typeName, nullable, list, listItemNullable };
}

/**
 * Builds an `AutoGeneratedType` (Object kind) from a union member's inline
 * object properties — used by the discriminator- and typename-based
 * resolveType generators for anonymous union members that need a synthesized
 * GraphQL object type.
 */
export function generateObjectTypeFromInlineObject(
  params: GenerateObjectTypeFromInlineObjectParams,
): AutoGeneratedType {
  const {
    inlineObjectMember,
    typeName,
    abstractTypeName,
    sourceFile,
    skipPropertyNames,
  } = params;
  const fields: FieldInfo[] = [];

  for (const property of inlineObjectMember.properties) {
    if (skipPropertyNames.has(property.name)) {
      continue;
    }
    fields.push({
      name: property.name,
      type: convertUnionMemberPropertyType(property),
      description: property.description,
      deprecated: property.deprecated,
      directives: null,
      defaultValue: null,
    });
  }

  return {
    name: typeName,
    kind: "Object",
    fields,
    enumValues: null,
    unionMembers: null,
    needsStringEnumMapping: false,
    sourceLocation: { file: sourceFile, line: 1, column: 1 },
    generatedFrom: {
      parentTypeName: abstractTypeName,
      fieldPath: [],
      context: "typeField",
    },
    description: null,
    // No source: InlineObjectMember carries only properties, not a
    // type-level TSDoc tag (these are synthesized per union member, not
    // sourced from a single type alias).
    deprecated: null,
    resolveTypeFieldPattern: null,
  };
}
